import diagnostics_channel from 'node:diagnostics_channel';
import cluster from 'node:cluster';

const commands = diagnostics_channel.channel('integration:orders-adapter:cmd');
const status = diagnostics_channel.channel('integration:orders-adapter:status');

diagnostics_channel.subscribe('integration:orders-adapter:cmd', ({ id, op }) => {
  const applied = apply(op);                                  // 'pause' | 'resume' | 'flush-stats'
  status.publish({ id, op, applied, at: Date.now() });        // correlated ack + status
});

process.on('SIGTERM', () => { drain().finally(() => process.exit(0)); });
if (cluster.isPrimary) for (const id in cluster.workers) cluster.workers[id].send({ op: 'flush-stats' });

const nc = await connect({ servers: 'nats://nats.internal:4222' });

const sub = nc.subscribe('control.orders-adapter.cmd', { callback: async (err, msg) => {
  if (err) return;
  const cmd = JSON.parse(sc.decode(msg.data));
  const applied = await apply(cmd.op);                       // idempotent command handler
  msg.respond(sc.encode(JSON.stringify({ id: cmd.id, applied, status: snapshot() })));
}});

await nc.publish('control.*.cmd', sc.encode(JSON.stringify({ op: 'flush-stats' })));  // fan-out
setInterval(() => nc.publish('control.orders-adapter.status', sc.encode(JSON.stringify(snapshot()))), 5000);
